    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*45, 0.075, 1.8, 1.15]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const d2 = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2 += Math.sin(d2*f*0.5+t*sp*0.8+2.0)*w;
    iS2 += Math.sin(d2*f*0.4-t*sp*0.5+0.8)*w;
  }
  const act = aS/8, inh = iS/8, act2 = aS2/8, inh2 = iS2/8;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.8)+Math.sin(fx*0.028-fy*0.038+t*1.1))/2
    + Math.sin((fx+fy)*0.11+t*2.5)*0.2 + Math.sin((fx-fy)*0.09-t*2.0)*0.2
