  const rd2 = Math.tanh((act2 - inh2*0.6 + bg*0.25 - spiral*0.4 + micro)*1.8);
  const cross = Math.tanh((rd1*0.6+rd2*0.4 + Math.sin(rd1*rd2*6+t)*0.3)*1.5);
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.5+Math.sin(fx*0.22-fy*0.1+t*1.3)*0.3)*1.4)*0.25;
  const blend = cross*0.7+cell*0.3, v = blend*0.5+0.5;
